// eye_sets.h: the eye looks built into the firmware.
// Each eye_set_<name>.h is generated by tools/eyegen/eyegen.py (see its README). The Mac switches
// between them at runtime with "LOOK <name>" (skull.py does this when it changes modes).
// The first set is the look at power-on. To add one, generate eye_set_<name>.h and list it here.
#pragma once
#include "eye_art.h"
#include "eye_set_glow.h"     // glowing red pupils on a black sclera: skull mode
#include "eye_set_hazel.h"    // natural hazel eyes: presenter mode

#define EYE_SET(ns) { #ns, eyeart::ns::sclera, eyeart::ns::iris, eyeart::ns::pupil_ramp, eyeart::ns::glint }

namespace eyeart {
static const EyeSet SETS[] = { EYE_SET(glow), EYE_SET(hazel) };
constexpr int NUM_SETS = sizeof(SETS) / sizeof(SETS[0]);
}  // namespace eyeart
